package game.agent.eval;
import game.agent.growth.*;import game.agent.llm.*;import game.agent.runtime.*;import game.agent.persistence.*;import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class EvaluationPlatformTest {
 @TempDir Path dir;
 @Test void lateUsageUpdatesCancelledBatchReportWithoutRestart(){MemoryStore store=new MemoryStore();EvaluationService service=new EvaluationService("owner",store,providers(),Runnable::run);Map<String,Object> p=params();p.put("models",Arrays.asList("baseline"));p.put("scenarios",Arrays.asList("information"));service.command(command(service,"CREATE",p));Map<String,Object> batch=Json.asObject(Json.asArray(service.snapshot().get("batches")).get(0));String id=(String)batch.get("id");service.command(command(service,"CANCEL",Json.object("batchId",id)));Map<String,Object> row=Json.asObject(Json.asArray(service.report(id).get("cases")).get(0));String run=(String)row.get("id");store.save("evaluation:owner:"+run+":usage",Json.object("issued",1,"calls",Arrays.asList(Json.object("callIndex",1,"success",true,"latencyMs",1.0,"usage",Json.object("inputTokens",10,"outputTokens",2,"totalTokens",12)))));Map<String,Object> report=service.report(id);assertEquals(12L,Json.asObject(Json.asObject(Json.asArray(report.get("cases")).get(0)).get("metrics")).get("totalTokens"));assertEquals(12L,Json.asObject(Json.asArray(report.get("comparison")).get(0)).get("totalTokens"));assertEquals("CANCELLED",report.get("status"));assertEquals(12L,Json.asObject(Json.asObject(Json.asArray(Json.asObject(Json.asArray(service.snapshot().get("batches")).get(0)).get("cases")).get(0)).get("metrics")).get("totalTokens"));}
 @Test void unavailableProviderEndsCaseAndAllowsFollowingBaselineBatch(){EvaluationProviders unavailable=new EvaluationProviders(Arrays.asList("missing","baseline"),1000,m->{if("missing".equals(m))throw new ProviderException(ProviderException.Code.CONFIGURATION);return EvaluationRun.baseline();});EvaluationService service=new EvaluationService("owner",null,unavailable,Runnable::run);Map<String,Object> p=params();p.put("models",Arrays.asList("missing"));p.put("scenarios",Arrays.asList("information"));service.command(command(service,"CREATE",p));p=new LinkedHashMap<>(p);p.put("models",Arrays.asList("baseline"));service.command(command(service,"CREATE",p));for(int i=1;i<30;i++)service.tick(i);List<Object> batches=Json.asArray(service.snapshot().get("batches"));assertEquals("COMPLETED_WITH_FAILURES",Json.asObject(batches.get(0)).get("status"));assertEquals("COMPLETED",Json.asObject(batches.get(1)).get("status"));}
 static Map<String,Object> spec(String scenario){return Json.object("id",UUID.randomUUID().toString(),"scenario",scenario,"seed",11L,"repetition",1,"model","baseline","starter","TREECKO","decisions",100,"wallMillis",10000,"price",Collections.emptyMap());}
 static void finish(EvaluationRun run){for(long tick=1;tick<1000&&!run.terminal();tick++)run.tick(tick*10);assertEquals("COMPLETED",run.status(),Json.write(run.report(true)));}
 @Test void cursorMatchesJavaRandomAndContinuesAfterRestore(){EvaluationRandom actual=new EvaluationRandom(-11);Random expected=new Random(-11);for(int i=0;i<20;i++)assertEquals(expected.nextInt(),actual.nextInt());EvaluationRandom restored=EvaluationRandom.restore(actual.checkpoint());for(int i=0;i<100;i++)assertEquals(actual.nextInt(),restored.nextInt());assertEquals(actual.identity(),restored.identity());}
 @Test void restoredGrowthKeepsFutureWaveIdentitiesAndBattleCursor(){EvaluationRandom rng=new EvaluationRandom(11);GrowthWorld world=new GrowthWorld(rng::nextInt,rng::identity);world.startAdventure();world.starter("TREECKO");world.execute("go_to_region",Json.object("regionId","forest"));EvaluationRandom rng2=EvaluationRandom.restore(rng.checkpoint());GrowthWorld restored=GrowthWorld.restore(world.export(),rng2::nextInt,rng2::identity);for(int i=0;i<20;i++){Map<String,Object> args=Json.object("targetId","forest-1-0","moveId","POUND");assertEquals(world.execute("use_skill",args).getCode(),restored.execute("use_skill",args).getCode());assertEquals(Json.write(world.export()),Json.write(restored.export()));}assertEquals(Json.write(rng.checkpoint()),Json.write(rng2.checkpoint()));}
 @Test void allNativeScenariosCompleteWithLabelledBaseline(){for(String scenario:EvaluationRun.SCENARIOS){EvaluationRun run=new EvaluationRun(spec(scenario));run.resume(EvaluationRun.baseline(),Runnable::run,1000);finish(run);Map<String,Object> report=run.report(true);assertFalse(Json.asArray(report.get("trace")).isEmpty());assertNull(Json.asObject(report.get("metrics")).get("cost"));if(scenario.equals("shared")||scenario.equals("competition")){Map<String,Object> shared=Json.asObject(Json.asObject(Json.asObject(report.get("finalWorld")).get("quest")).get("cooperative"));long playerDelivered=0,agentDelivered=0;for(Object item:Json.asArray(shared.get("ledger"))){Map<String,Object> event=Json.asObject(item);if("DELIVER".equals(event.get("action"))){if("PLAYER".equals(event.get("actor")))playerDelivered+=EvaluationRandom.number(event.get("quantity"));else agentDelivered+=EvaluationRandom.number(event.get("quantity"));}}assertEquals(1,playerDelivered);assertEquals(2,agentDelivered);}if(scenario.equals("information")){Map<String,Object> finalWorld=Json.asObject(report.get("finalWorld"));assertEquals(2,finalWorld.get("infoStage"));}if(scenario.equals("fault"))assertEquals(1.0,Json.asObject(report.get("metrics")).get("recoverySuccessRate"));}}
 @Test void matchingCasesShareInitialFingerprintRegardlessOfModelAndRepetition(){for(String scenario:EvaluationRun.SCENARIOS){Map<String,Object> first=spec(scenario),second=new LinkedHashMap<>(first);second.put("model","other");second.put("repetition",2);assertEquals(new EvaluationRun(first).report(false).get("initialFingerprint"),new EvaluationRun(second).report(false).get("initialFingerprint"),scenario);}}
 @Test void committedWorldAndTraceContinueAfterPauseRestart(){EvaluationRun run=new EvaluationRun(spec("forest"));run.resume(EvaluationRun.baseline(),Runnable::run,1000);for(int i=1;i<6;i++)run.tick(i);run.pause();String savedWorld=Json.write(run.checkpoint().get("world"));EvaluationRun restored=EvaluationRun.restore(Json.asObject(Json.read(Json.write(run.checkpoint()))));assertEquals(savedWorld,Json.write(restored.checkpoint().get("world")));run.resume(EvaluationRun.baseline(),Runnable::run,1000);restored.resume(EvaluationRun.baseline(),Runnable::run,1000);finish(run);finish(restored);assertEquals(run.report(true).get("finalFingerprint"),restored.report(true).get("finalFingerprint"));assertEquals(Json.asArray(run.report(true).get("trace")).size(),Json.asArray(restored.report(true).get("trace")).size());}
 @Test void pendingDecisionCannotCommitAfterPause()throws Exception{ExecutorService worker=Executors.newSingleThreadExecutor();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);try{EvaluationRun run=new EvaluationRun(spec("forest"));run.resume(c->{entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}return new game.agent.tools.ToolRequest("late","go_to_region",Json.object("regionId","forest"));},worker,1000);run.tick(1);assertTrue(entered.await(1,TimeUnit.SECONDS));run.pause();String before=Json.write(run.checkpoint().get("world"));release.countDown();worker.shutdown();assertTrue(worker.awaitTermination(1,TimeUnit.SECONDS));run.tick(2);assertEquals(before,Json.write(run.checkpoint().get("world")));}finally{release.countDown();worker.shutdownNow();}}
 @Test void costSeparatesCachedWritesAndReasoningIsNotDoubleCharged(){Map<String,Object> price=EvaluationPricing.validate(Json.object("version","fixture-v1","currency","USD","input",2,"cachedInput",1,"output",4,"cacheWrite",3));Map<String,Object> usage=Json.object("inputTokens",100,"outputTokens",50,"totalTokens",150,"cachedInputTokens",20,"cacheWriteTokens",10,"reasoningOutputTokens",30);Map<String,Object> result=EvaluationPricing.cost(Arrays.asList(Json.object("usage",usage)),price);assertEquals(.00039,(Double)result.get("cost"),1e-12);assertEquals("fixture-v1",result.get("priceVersion"));assertThrows(IllegalArgumentException.class,()->EvaluationPricing.validate(Json.object("version","v1","currency","USD","input",Double.NaN,"cachedInput",0,"output",1,"cacheWrite",0)));usage.remove("cachedInputTokens");assertNull(EvaluationPricing.cost(Arrays.asList(Json.object("usage",usage)),price).get("cost"));}
 @Test void completionIntervalsRemainHonestForTinySamples(){List<Double> interval=EvaluationStatistics.wilson(2,2);assertTrue(interval.get(0)<.5);assertEquals(1,interval.get(1),1e-10);assertTrue(EvaluationStatistics.wilson(0,0).isEmpty());assertThrows(IllegalArgumentException.class,()->EvaluationStatistics.wilson(3,2));}
 static EvaluationProviders providers(){return new EvaluationProviders(Arrays.asList("baseline","other"),1000,m->EvaluationRun.baseline());}
 static Map<String,Object> params(){return Json.object("models",Arrays.asList("baseline","other"),"scenarios",Arrays.asList("forest","information","fault"),"seeds",Arrays.asList(11L),"repetitions",1,"starter","TREECKO","decisions",100,"wallMillis",10000,"prices",Collections.emptyMap());}
 static Map<String,Object> command(EvaluationService service,String name,Map<String,Object> params){return Json.object("requestId",UUID.randomUUID().toString(),"expectedRevision",service.snapshot().get("revision"),"command",name,"params",params);}
 @Test void ownerScopedQueueReceiptsRestartAndReplayUseAtomicStore(){try(FileWorldStore store=new FileWorldStore(dir)){EvaluationService service=new EvaluationService("alice",store,providers(),Runnable::run);Map<String,Object> create=command(service,"CREATE",params());service.command(create);service.command(create);assertEquals(1,Json.asArray(service.snapshot().get("batches")).size());service.tick(1);service.tick(2);service.close();EvaluationService restart=new EvaluationService("alice",store,providers(),Runnable::run);Map<String,Object> batch=Json.asObject(Json.asArray(restart.snapshot().get("batches")).get(0));assertEquals("PAUSED",batch.get("status"));restart.command(command(restart,"RESUME",Json.object("batchId",batch.get("id"))));for(int i=1;i<500;i++)restart.tick(i*10);Map<String,Object> report=restart.report((String)batch.get("id"));assertEquals("COMPLETED",report.get("status"),Json.write(report));assertEquals(2,Json.asArray(report.get("comparison")).size());Map<String,Object> row=Json.asObject(Json.asArray(report.get("cases")).get(0));assertFalse(Json.asArray(restart.replay((String)batch.get("id"),(String)row.get("id")).get("trace")).isEmpty());EvaluationService bob=new EvaluationService("bob",store,providers(),Runnable::run);assertThrows(NoSuchElementException.class,()->bob.report((String)batch.get("id")));}}
 @Test void malformedCreateHasNoPartialBatchOrProviderCall(){EvaluationService service=new EvaluationService("owner",null,providers(),Runnable::run);Map<String,Object> p=params();p.put("models",Arrays.asList("not-configured"));assertThrows(IllegalArgumentException.class,()->service.command(command(service,"CREATE",p)));assertTrue(Json.asArray(service.snapshot().get("batches")).isEmpty());Map<String,Object> stale=command(service,"CREATE",params());stale.put("expectedRevision",99);assertThrows(IllegalStateException.class,()->service.command(stale));}
 @Test void cancellationStopsFutureCases(){EvaluationService service=new EvaluationService("owner",null,providers(),Runnable::run);service.command(command(service,"CREATE",params()));Map<String,Object> batch=Json.asObject(Json.asArray(service.snapshot().get("batches")).get(0));service.tick(1);service.command(command(service,"CANCEL",Json.object("batchId",batch.get("id"))));for(int i=2;i<30;i++)service.tick(i);assertEquals("CANCELLED",service.report((String)batch.get("id")).get("status"));for(Object v:Json.asArray(service.report((String)batch.get("id")).get("cases")))assertEquals("CANCELLED",Json.asObject(v).get("status"));}

 static final class MemoryStore implements WorldStore {final Map<String,Map<String,Object>> data=new HashMap<>();boolean failIndex;public void save(String key,Map<String,Object> value){if(failIndex&&key.equals("evaluation:owner")){failIndex=false;throw new StoreException(StoreException.Code.IO_ERROR);}data.put(key,Json.asObject(Json.read(Json.write(value))));}public Map<String,Object> load(String key){Map<String,Object> row=data.get(key);return row==null?null:Json.asObject(Json.read(Json.write(row)));}public void close(){}}
 @Test void runCommitSurvivesCrashBeforeIndexCommit(){MemoryStore store=new MemoryStore();EvaluationService service=new EvaluationService("owner",store,providers(),Runnable::run);Map<String,Object> params=params();params.put("models",Arrays.asList("baseline"));params.put("scenarios",Arrays.asList("information"));service.command(command(service,"CREATE",params));Map<String,Object> batch=Json.asObject(Json.asArray(service.snapshot().get("batches")).get(0));Map<String,Object> stale=store.load("evaluation:owner");for(int i=1;i<20;i++)service.tick(i);assertEquals("COMPLETED",service.report((String)batch.get("id")).get("status"));store.save("evaluation:owner",stale);EvaluationService restart=new EvaluationService("owner",store,providers(),Runnable::run);assertEquals("COMPLETED",restart.report((String)batch.get("id")).get("status"));}
 @Test void storageFailureFreezesAndRecoversLastCommittedWorld(){MemoryStore store=new MemoryStore();EvaluationService service=new EvaluationService("owner",store,providers(),Runnable::run);service.command(command(service,"CREATE",params()));service.tick(1);store.failIndex=true;service.tick(2);assertEquals("STORAGE_ERROR",service.snapshot().get("status"));service.command(command(service,"RECOVER",Collections.emptyMap()));assertEquals("READY",service.snapshot().get("status"));Map<String,Object> batch=Json.asObject(Json.asArray(service.snapshot().get("batches")).get(0));assertEquals("PAUSED",batch.get("status"));service.command(command(service,"RESUME",Json.object("batchId",batch.get("id"))));for(int i=3;i<500;i++)service.tick(i);assertEquals("COMPLETED",service.report((String)batch.get("id")).get("status"));}
 @Test void questCheckpointResumesWithoutDuplicatingContribution(){EvaluationRun first=new EvaluationRun(spec("competition"));first.resume(EvaluationRun.baseline(),Runnable::run,1000);for(int i=1;i<8;i++)first.tick(i);first.pause();EvaluationRun restored=EvaluationRun.restore(Json.asObject(Json.read(Json.write(first.checkpoint()))));assertEquals(first.report(true).get("finalFingerprint"),restored.report(true).get("finalFingerprint"));first.resume(EvaluationRun.baseline(),Runnable::run,1000);restored.resume(EvaluationRun.baseline(),Runnable::run,1000);finish(first);finish(restored);assertEquals(first.report(true).get("finalFingerprint"),restored.report(true).get("finalFingerprint"));}
 @Test void realPostgresRoundTripsEvaluationQueueAndReplay()throws Exception{String url=System.getProperty("pokemon.test.jdbcUrl");Assumptions.assumeTrue(url!=null);Class.forName("org.postgresql.Driver");try(WorldStore store=new JdbcWorldStore(()->java.sql.DriverManager.getConnection(url,System.getProperty("pokemon.test.jdbcUser","pokemon_v1"),""))){String owner="v4-test-"+UUID.randomUUID();EvaluationService service=new EvaluationService(owner,store,providers(),Runnable::run);Map<String,Object> params=params();params.put("models",Arrays.asList("baseline"));params.put("scenarios",Arrays.asList("information"));service.command(command(service,"CREATE",params));service.tick(1);service.close();EvaluationService restart=new EvaluationService(owner,store,providers(),Runnable::run);Map<String,Object> batch=Json.asObject(Json.asArray(restart.snapshot().get("batches")).get(0));restart.command(command(restart,"RESUME",Json.object("batchId",batch.get("id"))));for(int i=2;i<30;i++)restart.tick(i);assertEquals("COMPLETED",restart.report((String)batch.get("id")).get("status"));}}

 @Test void longTracePersistsBeyondLegacyNodeCapWithoutLosingActions(){try(FileWorldStore store=new FileWorldStore(dir)){EvaluationProviders providers=new EvaluationProviders(Arrays.asList("observer"),1000,m->c->new game.agent.tools.ToolRequest("idle","go_to_region",Json.object("regionId","lab")));EvaluationService service=new EvaluationService("observer",store,providers,Runnable::run);Map<String,Object> params=params();params.put("models",Arrays.asList("observer"));params.put("scenarios",Arrays.asList("forest"));service.command(command(service,"CREATE",params));Map<String,Object> batch=Json.asObject(Json.asArray(service.snapshot().get("batches")).get(0));for(int i=1;i<250;i++)service.tick(i);assertEquals("READY",service.snapshot().get("status"));Map<String,Object> report=service.report((String)batch.get("id"));assertEquals("COMPLETED_WITH_FAILURES",report.get("status"));Map<String,Object> row=Json.asObject(Json.asArray(report.get("cases")).get(0));Map<String,Object> replay=service.replay((String)batch.get("id"),(String)row.get("id"));assertEquals(100L,((Number)Json.asObject(replay.get("metrics")).get("actionSteps")).longValue());assertEquals(101,Json.asArray(replay.get("trace")).size());}}
 @Test void usageIsJournaledBeforeProviderAndAfterActualResponse(){List<Map<String,Object>> journal=new ArrayList<>();EvaluationRun run=new EvaluationRun(spec("information"));run.usageJournal(row->journal.add(Json.asObject(Json.read(Json.write(row)))));run.resume(EvaluationRun.baseline(),Runnable::run,1000);finish(run);assertEquals(4,journal.size());assertEquals(1L,((Number)journal.get(0).get("issued")).longValue());assertTrue(Json.asArray(journal.get(0).get("calls")).isEmpty());assertEquals(2,Json.asArray(journal.get(3).get("calls")).size());EvaluationRun restored=EvaluationRun.restore(run.checkpoint());restored.applyUsageJournal(Json.object("issued",3,"calls",journal.get(3).get("calls")));assertEquals(1L,Json.asObject(restored.report(false).get("metrics")).get("outstandingProviderCalls"));assertNull(Json.asObject(restored.report(false).get("metrics")).get("cost"));}
}
